const FeatureCard_data = [
    { title: "Wer ist Niklas Volland?", description: "Niklas Volland ist KI-Transformationsexperte, Keynote Speaker und strategischer Berater für Unternehmen, die Künstliche Intelligenz nicht ausprobieren, sondern strategisch verankern wollen. Als Partner von Microsoft und Google verbindet er Top-Wissensstand mit über 200 realen Transformationsprojekten und 120+ Keynotes. Mit mehr als 365.000 Followern plattformübergreifend führt er zudem eine der größten KI-Communities im DACH-Raum." },
    { title: "Welche Leistungen bietet Niklas Volland an?", description: "Drei Bausteine, alle im Premium-Segment: Keynotes für Konzern-Events und Top-Konferenzen, die skalierbare KI•POWERBOOST ACADEMY für die unternehmensweite Befähigung ganzer Belegschaften, sowie kuratierte Kollaborationen mit AI-Brands – ausgewählte Werbepartnerschaften mit Tools, die Niklas selbst produktiv nutzt und die seine Community mit 365.000+ Followern erreichen. Niklas arbeitet selektiv und ausschließlich mit Mandaten, die KI gezielt als zentralen strategischen Hebel für Wachstum und Effizienz nutzen." },
    { title: "Was unterscheidet Niklas von anderen KI-Speakern?", description: "Niklas bringt eine selten anzutreffende Kombination mit: enorm hohe Sensibilität und Empathie für Transformations-Themen, die Fähigkeit, Menschen zu begeistern, zu inspirieren und ihnen Ängste zu nehmen, sowie jahrelange Erfahrung in Technologie und Veränderungsprozessen. Als studierter Kommunikationswissenschaftler verbindet er Mensch und Technologie auf einzigartige Weise und macht KI dadurch nicht nur verständlich, sondern menschlich anschlussfähig." },
    { title: "Für welche Unternehmen arbeitet Niklas Volland?", description: "Schwerpunkt: Konzerne, gehobener Mittelstand und marktführende Unternehmen mit hohem Anspruch an Qualität und Wirkung. Branchen-Schwerpunkte sind Industrie, Finanzdienstleistung, Pharma, Versicherung und Tech. Mandate werden bewusst selektiv vergeben, um maximale Wirkung pro Engagement zu sichern." },
    { title: "Was kostet eine Zusammenarbeit mit Niklas Volland?", description: "Niklas positioniert sich konsequent im Premium-Segment. Investitionen variieren nach Format, Umfang und individueller Vorbereitung und werden im persönlichen Erstgespräch besprochen. Niklas hat bewusst keinen Tagessatz, weil er nicht für seine Zeit, sondern für seine Wirkung bezahlt wird." },
    { title: "Wie buche ich Niklas Volland?", description: "Anfragen laufen direkt über das Kontaktformular auf niklasvolland.de. Empfohlener Vorlauf: mindestens 6 Wochen, bei großen Konzernformaten 3 bis 6 Monate. Die Verfügbarkeit ist aufgrund selektiver Mandatswahl begrenzt." },
    { title: "Welche Themen behandelt Niklas in seinen Keynotes?", description: "Schwerpunkte: KI-Strategie für Vorstand und C-Level, generative und agentische KI im Unternehmen, KI-getriebene Geschäftsmodelle, Change Management bei KI-Einführung, Mitarbeiter-Enablement und die Zukunft der Arbeit mit KI. Jedes Format wird vor dem Auftritt individuell auf Branche, Zielgruppe und Business-Ziel zugeschnitten." },
    { title: "Bietet Niklas auch skalierbare Formate für ganze Belegschaften?", description: "Ja. Die KI•POWERBOOST ACADEMY ermöglicht es Unternehmen, ihre komplette Belegschaft per Jahreslizenz auf KI-Niveau zu bringen, ohne dass Niklas vor Ort sein muss. Damit lässt sich die Wirkung einer Keynote nachhaltig in der gesamten Organisation verankern." }
];
